import { Plus, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useState } from 'react';
import type { I18nText } from '@/lib/i18n-text';
import { createI18nText } from '@/lib/i18n-text';

interface I18nTagInputProps {
  value: I18nText[];
  onChange: (val: I18nText[]) => void;
  label?: string;
  addLabel?: string;
  placeholder?: string;
  emptyText?: string;
  disabled?: boolean;
  className?: string;
}

const LANGS: { code: 'en' | 'zh' | 'es' | 'ja'; label: string }[] = [
  { code: 'en', label: 'EN' },
  { code: 'zh', label: '中' },
  { code: 'es', label: 'ES' },
  { code: 'ja', label: '日' },
];

export default function I18nTagInput({
  value,
  onChange,
  label,
  addLabel = 'Add Item',
  placeholder = 'Enter text...',
  emptyText = 'No items yet.',
  disabled = false,
  className = '',
}: I18nTagInputProps) {
  const [activeLang, setActiveLang] = useState<'en' | 'zh' | 'es' | 'ja'>('en');

  const handleAdd = () => {
    onChange([...value, createI18nText('')]);
  };

  const handleRemove = (index: number) => {
    onChange(value.filter((_, i) => i !== index));
  };

  const handleChange = (index: number, lang: 'en' | 'zh' | 'es' | 'ja', val: string) => {
    const next = value.map((item, i) => (i === index ? { ...item, [lang]: val } : item));
    onChange(next);
  };

  const currentValue = (item: I18nText) => item[activeLang] ?? '';

  return (
    <div className={`space-y-2 ${className}`}>
      <div className="flex items-center justify-between">
        {label && <label className="text-xs font-medium text-foreground">{label}</label>}
        <div className="flex items-center gap-1 ml-auto">
          <div className="flex items-center rounded-md border border-border bg-muted/30 p-0.5">
            {LANGS.map((lang) => (
              <button
                key={lang.code}
                type="button"
                onClick={() => setActiveLang(lang.code)}
                className={`relative px-2 py-0.5 text-[11px] font-medium rounded-sm transition-colors ${
                  activeLang === lang.code
                    ? 'bg-primary text-primary-foreground'
                    : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                {lang.label}
              </button>
            ))}
          </div>
          <Button
            type="button"
            size="sm"
            variant="outline"
            onClick={handleAdd}
            disabled={disabled}
            className="h-7 text-xs"
          >
            <Plus className="size-3 mr-1" />
            {addLabel}
          </Button>
        </div>
      </div>

      <div className="space-y-2">
        {value.map((item, index) => (
          <div key={index} className="flex items-center gap-2">
            <Input
              value={currentValue(item)}
              onChange={(e) => handleChange(index, activeLang, e.target.value)}
              placeholder={placeholder}
              className="flex-1 h-9"
              disabled={disabled}
            />
            <Button
              type="button"
              size="icon"
              variant="outline"
              onClick={() => handleRemove(index)}
              disabled={disabled}
              className="h-9 w-9 shrink-0 text-destructive hover:bg-destructive/10 border-destructive/30"
            >
              <X className="size-4" />
            </Button>
          </div>
        ))}
      </div>

      {value.length === 0 && (
        <p className="text-xs text-muted-foreground text-center py-3 border border-dashed border-border/60 rounded-sm">
          {emptyText}
        </p>
      )}
    </div>
  );
}
